<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import Icon from './HelmLabIcon.vue';
import ReleaseTrackers from './ReleaseTrackers.vue';
import HomeLayoutPicker from './HomeLayoutPicker.vue';
import {homeLayout} from './home-preferences.mjs';
import {homeBriefing} from './home-layout.mjs';
import {dailyReadiness,dailyReadinessBusy,dailyReadinessError,changeDailyReadiness} from './daily-readiness-store.mjs';
import {myWorkSnapshot,refreshMyWork,myWorkRefreshing,myWorkError} from './my-work-store.mjs';
import {testPackageSummaries,openTestPackage} from './test-packages-store.mjs';
import {myWorkRows,myWorkMetrics} from './my-work.mjs';
import {openIssueReadiness} from './issue-readiness-store.mjs';
import {activeTab,previousWorkspaceTab,state,bootPending,refreshError,refreshChecks,manualRefreshInFlight,setActivePanelTab} from './store.js';
import {filterWorkspaceTools,homeSnapshot,toolGroups,workspaceTool} from './home-workspace.mjs';
const work=computed(()=>myWorkSnapshot.value);
const metrics=computed(()=>myWorkMetrics(myWorkRows(work.value,testPackageSummaries.value)));
const recent=computed(()=>[...testPackageSummaries.value].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,4));
const report=computed(()=>dailyReadiness.value.report);
const briefing=computed(()=>homeBriefing(report.value,work.value));
const readyIssues=computed(()=>[...briefing.value.entries].filter(entry=>!entry.changed&&entry.verdict==='ready').sort((a,b)=>Number(!!b.workflow?.greenLight)-Number(!!a.workflow?.greenLight)).slice(0,3));
const scanning=computed(()=>report.value?.status==='running');
const snapshot=computed(()=>homeSnapshot(state.value,{bootPending:bootPending.value,error:refreshError.value}));
const resume=computed(()=>workspaceTool(previousWorkspaceTab.value));
const query=ref(''),directoryOpen=ref(false),searchInput=ref(null);
const groups=computed(()=>toolGroups.map(group=>({...group,tools:filterWorkspaceTools(query.value).filter(tool=>tool.group===group.id)})).filter(group=>group.tools.length));
const sections=computed(()=>homeLayout.value==='ready'?['ready','continue']:['continue','ready']);
const dateLabel=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());
const observed=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
async function findTools(){directoryOpen.value=true;await nextTick();searchInput.value?.focus();searchInput.value?.scrollIntoView({block:'center',behavior:'instant'});}
function shortcut(event){if(activeTab.value==='home'&&event.key==='/'&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!event.target.closest?.('input,textarea,select,[contenteditable="true"]')){event.preventDefault();findTools();}}
onMounted(()=>{window.addEventListener('keydown',shortcut);void refreshMyWork();});
onBeforeUnmount(()=>window.removeEventListener('keydown',shortcut));
watch(activeTab,tab=>{if(tab==='home')void refreshMyWork();});
</script>
<template>
 <div class="quiet-home">
  <header class="qh-heading"><div><span class="qh-eyebrow">{{dateLabel}}</span><h1 id="home-title" tabindex="-1">Your work, in view.</h1><p>{{homeLayout==='ready'?'A clear view of what’s ready and what needs you.':'Pick up where you left off.'}}</p></div><details class="qh-customize"><summary><Icon name="sliders"/>Personalize Home</summary><div><HomeLayoutPicker name="home-layout-choice"/></div></details></header>
  <p v-if="myWorkError||dailyReadinessError" class="qh-notice" role="status">{{myWorkError||dailyReadinessError}}</p>
  <div v-if="snapshot.cloud.length||snapshot.localBusy||snapshot.stale||snapshot.checking" class="qh-activity" role="status"><Icon :name="snapshot.stale?'signal':'pulse'"/><span>{{snapshot.stale?'Workspace status may be out of date.':snapshot.checking?'Checking workspace…':snapshot.cloud.map(item=>item.label).join(' · ')||'Local operation running'}}<small v-if="snapshot.cloud.length&&!snapshot.stale">Keep Runway open while it finishes.</small></span><button v-if="snapshot.stale" :disabled="manualRefreshInFlight" @click="refreshChecks">Refresh</button><button v-else @click="setActivePanelTab(snapshot.cloud[0]?.tab||(state.steve?.operation?.running?'steve':snapshot.localBusy?'k3d':'runs'))">View activity <Icon name="arrow"/></button></div>
  <ReleaseTrackers/>
  <div class="qh-layout">
   <div class="qh-main">
    <section v-for="section in sections" :key="section" class="qh-section" :class="{'qh-feature':section===sections[0]}" :aria-label="section==='continue'?'Continue working':'Readiness briefing'">
     <template v-if="section==='continue'">
      <div class="qh-section-top"><div><span class="qh-eyebrow">Your recent work</span><h2>Continue working</h2></div><button class="qh-link" @click="setActivePanelTab('packages')">All packages <Icon name="arrow"/></button></div>
      <button v-if="resume" class="qh-resume" @click="setActivePanelTab(resume.id)"><span class="qh-icon"><Icon :name="resume.icon"/></span><span><small>Last workspace</small><strong>Return to {{resume.label}}</strong></span><Icon name="arrow"/></button>
      <div v-if="recent.length" class="qh-package-list"><button v-for="pkg in recent" :key="pkg.id" @click="openTestPackage(pkg.id)"><span class="qh-package-mark"><Icon name="folder"/></span><span><strong>{{pkg.title}}</strong><small>{{pkg.cases?.length||0}} {{pkg.cases?.length===1?'test case':'test cases'}} · {{pkg.status?.replaceAll('_',' ')||'planning'}}</small></span><span class="qh-updated">{{observed(pkg.updatedAt)}}</span><Icon name="arrow"/></button></div>
      <div v-else class="qh-empty"><Icon name="folder"/><h3>Start with your milestone.</h3><p>Bring in your issues and give your test plans a home.</p><button class="qh-primary" @click="setActivePanelTab('my-work')">Choose a milestone <Icon name="arrow"/></button></div>
     </template>
     <template v-else>
      <div class="qh-section-top"><div><span class="qh-eyebrow">{{briefing.available?'Saved observations':'Your next check'}}</span><h2>Ready to test</h2></div><button class="qh-link" :disabled="scanning||dailyReadinessBusy||!work" @click="changeDailyReadiness('scan')"><Icon name="refresh" :class="{'qh-spin':scanning}"/>{{scanning?'Scanning…':'Scan now'}}</button></div>
      <div class="qh-readiness-counts"><div :data-positive="briefing.available&&briefing.green>0"><strong>{{briefing.available?briefing.green:'—'}}</strong><span>Green lights</span></div><div><strong>{{briefing.available?briefing.builds:'—'}}</strong><span>Fixes in builds</span></div><div><strong>{{work?metrics.needsPlan:'—'}}</strong><span>Need a test plan</span></div></div>
      <p v-if="!briefing.available" class="qh-caption">{{work?briefing.reason:'Choose a milestone in My Work to start your briefing.'}}</p>
      <p v-else class="qh-caption">{{observed(report.startedAt)}} · {{scanning?`${report.checked} of ${report.total} checked`:report.status}}<span v-if="!scanning"> · Green means workflow and build evidence agree.</span></p>
      <div v-if="readyIssues.length" class="qh-ready-list"><button v-for="entry in readyIssues" :key="entry.issueUrl" @click="openIssueReadiness(entry.issueUrl)"><span class="qh-signal" :data-green="!!entry.workflow?.greenLight"><Icon :name="entry.workflow?.greenLight?'check':'branch'"/></span><span><small>#{{entry.number}} · {{entry.workflow?.greenLight?'Ready for QA':'Build available · confirm status'}}</small><strong>{{entry.title}}</strong></span><Icon name="arrow"/></button></div>
      <p v-else-if="briefing.available" class="qh-caption">{{scanning?'Results appear as each check finishes.':'No current issues have proven build inclusion in this report.'}}</p>
      <button class="qh-link qh-view-report" @click="setActivePanelTab('my-work')">Open My Work <Icon name="arrow"/></button>
     </template>
    </section>
   </div>
   <aside class="qh-aside" aria-label="Workspace context">
    <section class="qh-milestone"><span class="qh-eyebrow">Current milestone</span><h2>{{work?.milestone.title||'Make room for your work.'}}</h2><p>{{work?.config.repo||'Issues, plans, and evidence together.'}}</p><template v-if="work"><div class="qh-milestone-total"><strong>{{metrics.open}}</strong><span>issues remaining</span></div><div class="qh-coverage" role="img" :aria-label="`${metrics.planned} of ${metrics.open} remaining issues have saved test cases`"><i :style="{width:(metrics.open?metrics.planned/metrics.open*100:0)+'%'}"></i></div><p class="qh-caption">{{metrics.planned}} with test cases · {{metrics.needsPlan}} to prepare</p></template><button class="qh-link" @click="setActivePanelTab('my-work')">{{work?'View milestone':'Set up My Work'}} <Icon name="arrow"/></button><small v-if="myWorkRefreshing" role="status">Refreshing issues…</small></section>
    <section class="qh-environments"><div class="qh-section-top"><h3>Environments</h3><Icon name="server"/></div><button @click="setActivePanelTab('runs')"><span>Recorded runs</span><strong>{{snapshot.known?snapshot.runs:'—'}}</strong></button><button @click="setActivePanelTab('k3d')"><span>Active K3D clusters</span><strong>{{snapshot.known?snapshot.k3d:'—'}}</strong></button><button @click="setActivePanelTab('steve')"><span>Active Steve sessions</span><strong>{{snapshot.known?snapshot.steve:'—'}}</strong></button><p class="qh-caption" v-if="snapshot.stale">Last known counts · refresh to update.</p><button class="qh-link qh-environment-action" @click="setActivePanelTab('clusters')">Open clusters <Icon name="arrow"/></button></section>
    <nav class="qh-shortcuts" aria-label="Quick tools"><h3>Within reach</h3><button v-for="id in ['issues','pr-builds','images','tests']" :key="id" @click="setActivePanelTab(id)"><Icon :name="workspaceTool(id).icon"/><span>{{workspaceTool(id).label}}</span><Icon name="arrow"/></button></nav>
   </aside>
  </div>
  <details class="qh-directory" :open="directoryOpen" @toggle="directoryOpen=$event.target.open"><summary><span>All workspaces</span><small>Find a tool when you need it</small><Icon name="chevron"/></summary><div class="qh-directory-content"><label class="qh-search"><Icon name="search"/><input ref="searchInput" v-model="query" type="search" aria-label="Find a workspace" placeholder="Search tools…" @keydown.esc="query=''"/><kbd>/</kbd></label><div class="qh-tools"><section v-for="group in groups" :key="group.id"><h3>{{group.title}}</h3><button v-for="tool in group.tools" :key="tool.id" @click="setActivePanelTab(tool.id)"><Icon :name="tool.icon"/><span><strong>{{tool.label}}</strong><small>{{tool.description}}</small></span></button></section></div><p v-if="!groups.length" class="qh-caption">No matching workspaces. Try “image”, “test”, or “cluster”.</p></div></details>
 </div>
</template>
<style scoped>
.quiet-home{max-width:1440px;margin:0 auto;padding:28px 12px 36px;color:var(--runway-ink);font-size:13px;line-height:1.6}.quiet-home button,.quiet-home summary{cursor:pointer}.quiet-home button:disabled{opacity:.55;cursor:default}.quiet-home :focus-visible{outline:2px solid var(--runway-accent);outline-offset:4px}.qh-heading,.qh-section-top{display:flex;align-items:center;justify-content:space-between;gap:20px}.qh-heading{margin-bottom:34px;align-items:flex-start}.qh-eyebrow{font-size:10px;letter-spacing:.11em;text-transform:uppercase;color:var(--runway-muted);font-weight:600}.qh-heading h1{font-size:clamp(34px,4vw,48px);letter-spacing:-.045em;line-height:1.2;font-weight:620;margin:9px 0}.qh-heading p{color:var(--runway-muted);font-size:14px}.qh-customize{position:relative;z-index:5;margin-top:10px}.qh-customize>summary{display:flex;align-items:center;gap:8px;list-style:none;font-size:12px;border:1px solid var(--runway-border);border-radius:9px;padding:9px 12px;background:var(--runway-card)}.qh-customize>div{position:absolute;right:0;top:52px;width:min(600px,calc(100vw - 72px));padding:24px;border:1px solid var(--runway-border);border-radius:16px;background:var(--runway-card);box-shadow:var(--runway-shadow)}.qh-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:36px;align-items:start}.qh-main{display:grid;gap:28px;min-width:0}.qh-section{border:1px solid var(--runway-border);border-radius:16px;background:var(--runway-card);padding:26px;min-width:0;animation:qh-enter 180ms ease-out}.qh-feature{border-top-color:color-mix(in srgb,var(--runway-accent) 40%,var(--runway-border))}.qh-section h2,.qh-milestone h2{font-size:23px;line-height:1.3;letter-spacing:-.03em;font-weight:620;margin-top:5px}.qh-section-top{margin-bottom:22px}.qh-link{display:inline-flex;align-items:center;gap:8px;color:var(--runway-accent);font-size:12px;font-weight:550;white-space:nowrap}.qh-link svg,.quiet-home svg{width:17px;height:17px;flex-shrink:0}.qh-primary{display:inline-flex;align-items:center;gap:10px;background:var(--runway-accent);color:var(--runway-card);border-radius:9px;padding:11px 16px;font-weight:600;margin-top:18px}.qh-resume{width:100%;display:flex;align-items:center;gap:15px;text-align:left;border:1px solid var(--runway-border);background:var(--runway-soft);border-radius:11px;padding:16px;margin-bottom:10px}.qh-resume>span:nth-child(2){flex:1}.qh-resume small{font-size:10px;color:var(--runway-muted);display:block}.qh-resume strong{font-size:14px;font-weight:550}.qh-icon,.qh-package-mark{display:grid;place-items:center;color:var(--runway-muted)}.qh-icon{width:37px;height:37px;border:1px solid var(--runway-border);border-radius:9px;background:var(--runway-card)}.qh-package-list>button,.qh-ready-list>button{width:100%;display:flex;align-items:center;gap:14px;text-align:left;padding:17px 0;border-bottom:1px solid var(--runway-border);transition:background 140ms}.qh-package-list>button:last-child,.qh-ready-list>button:last-child{border-bottom:0}.qh-package-list>button>span:nth-child(2),.qh-ready-list>button>span:nth-child(2){flex:1;min-width:0}.qh-package-list strong,.qh-ready-list strong{display:block;font-size:13px;font-weight:550;line-height:1.6;overflow-wrap:anywhere}.qh-package-list small,.qh-ready-list small,.qh-updated{font-size:10px;color:var(--runway-muted)}.qh-package-list button>svg,.qh-ready-list button>svg{color:var(--runway-muted)}.qh-package-list button:hover strong,.qh-ready-list button:hover strong{color:var(--runway-accent)}.qh-updated{white-space:nowrap}.qh-empty{padding:25px 5px 15px;text-align:left}.qh-empty>svg{width:28px;height:28px;margin-bottom:16px;color:var(--runway-muted)}.qh-empty h3{font-size:18px;font-weight:550}.qh-empty p{color:var(--runway-muted);margin-top:6px;max-width:350px}.qh-readiness-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:5px 0 18px;gap:20px}.qh-readiness-counts>div+div{border-left:1px solid var(--runway-border);padding-left:20px}.qh-readiness-counts strong{font-size:35px;line-height:1.25;font-weight:550;letter-spacing:-.04em;font-variant-numeric:tabular-nums;display:block}.qh-readiness-counts [data-positive=true] strong{color:var(--runway-accent)}.qh-readiness-counts span{color:var(--runway-muted);font-size:11px}.qh-caption{font-size:11px!important;color:var(--runway-muted);line-height:1.7}.qh-signal{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:var(--runway-soft);color:var(--runway-gold)}.qh-signal[data-green=true]{background:var(--runway-accent-soft);color:var(--runway-accent)}.qh-view-report{margin-top:18px}.qh-aside{display:grid;gap:28px}.qh-milestone{border-bottom:1px solid var(--runway-border);padding:5px 0 27px}.qh-milestone h2{font-size:26px;margin:10px 0 5px}.qh-milestone>p{color:var(--runway-muted);font-size:12px}.qh-milestone-total{display:flex;align-items:baseline;gap:10px;margin:22px 0 12px}.qh-milestone-total strong{font-size:32px;font-weight:550;letter-spacing:-.04em}.qh-milestone-total span{font-size:12px;color:var(--runway-muted)}.qh-coverage{height:4px;border-radius:4px;background:var(--runway-border);overflow:hidden;margin-bottom:12px}.qh-coverage i{display:block;height:100%;background:var(--runway-accent)}.qh-milestone>.qh-link{margin-top:17px}.qh-milestone>small{display:block;font-size:10px;color:var(--runway-muted);margin-top:10px}.qh-aside h3{font-size:13px;font-weight:600}.qh-environments .qh-section-top{margin-bottom:10px}.qh-environments>.qh-section-top svg{color:var(--runway-muted)}.qh-environments>button{display:flex;width:100%;justify-content:space-between;align-items:center;padding:9px 0;font-size:12px}.qh-environments button>span{color:var(--runway-muted)}.qh-environments button>strong{font-size:13px;font-weight:550}.qh-environments>.qh-environment-action{justify-content:flex-start;gap:8px;margin-top:10px}.qh-shortcuts{border-top:1px solid var(--runway-border);padding-top:22px}.qh-shortcuts h3{margin-bottom:12px}.qh-shortcuts button{display:flex;align-items:center;gap:10px;padding:9px 0;width:100%;font-size:12px;color:var(--runway-muted)}.qh-shortcuts button span{flex:1;text-align:left}.qh-shortcuts button:hover{color:var(--runway-ink)}.qh-activity,.qh-notice{display:flex;align-items:center;gap:12px;border:1px solid var(--runway-border);border-radius:10px;padding:12px 16px;margin-bottom:25px;background:var(--runway-soft);font-size:12px}.qh-activity>span{flex:1}.qh-activity small{display:block;color:var(--runway-muted);font-size:10px}.qh-activity button{display:flex;gap:8px;align-items:center;color:var(--runway-accent)}.qh-notice{color:var(--runway-gold);overflow-wrap:anywhere}.qh-directory{border-top:1px solid var(--runway-border);margin-top:38px}.qh-directory>summary{display:flex;gap:14px;align-items:center;list-style:none;padding:22px 0;font-size:13px;font-weight:550}.qh-directory summary small{font-size:11px;font-weight:400;color:var(--runway-muted);flex:1}.qh-directory>summary>svg{color:var(--runway-muted);transition:transform 150ms}.qh-directory[open]>summary>svg{transform:rotate(180deg)}.qh-search{display:flex;gap:12px;align-items:center;border:1px solid var(--runway-border);padding:11px 14px;border-radius:9px;background:var(--runway-card);max-width:420px;margin-bottom:25px;color:var(--runway-muted)}.qh-search input{background:transparent;border:0;outline:0;min-width:0;flex:1;color:var(--runway-ink);font-size:12px}.qh-search:focus-within{outline:2px solid var(--runway-accent);outline-offset:2px}.qh-search kbd{font-size:11px}.qh-tools{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.qh-tools h3{font-size:12px;color:var(--runway-muted);margin-bottom:12px}.qh-tools button{display:flex;align-items:flex-start;gap:12px;padding:12px 0;text-align:left;width:100%}.qh-tools button>svg{margin-top:3px;color:var(--runway-muted)}.qh-tools strong{font-size:12px;font-weight:550;display:block}.qh-tools small{font-size:11px;color:var(--runway-muted);line-height:1.6;display:block;margin-top:3px}.qh-tools button:hover strong{color:var(--runway-accent)}.qh-spin{animation:qh-spin 1.2s linear infinite}@keyframes qh-spin{to{transform:rotate(360deg)}}@keyframes qh-enter{from{opacity:.5;transform:translateY(3px)}to{opacity:1;transform:translateY(0)}}@media(max-width:1000px){.qh-layout{grid-template-columns:minmax(0,1fr) 240px;gap:24px}.qh-updated{display:none}}@media(max-width:760px){.quiet-home{padding:20px 0}.qh-layout{grid-template-columns:1fr}.qh-heading{flex-wrap:wrap;gap:12px}.qh-heading h1{font-size:36px}.qh-heading{position:relative}.qh-customize{position:static}.qh-customize>div{right:0;left:0;top:100%;width:auto}.qh-section{padding:20px}.qh-aside{grid-template-columns:1fr 1fr;gap:22px}.qh-shortcuts{grid-column:span 2}.qh-tools{grid-template-columns:1fr}.qh-readiness-counts{gap:12px}.qh-readiness-counts>div+div{padding-left:12px}.qh-section-top{gap:12px}.qh-section h2{font-size:21px}}@media(max-width:480px){.qh-aside{grid-template-columns:1fr}.qh-shortcuts{grid-column:auto}.qh-directory summary small{display:none}.qh-directory summary>span{flex:1}}@media(prefers-reduced-motion:reduce){.quiet-home *{animation:none!important;transition:none!important}}
</style>
